def feature(n,title,text,inside,tags,reverse=False,blue=False):
    return f'<section class="feature-row'+(' reverse' if reverse else '')+f' reveal"><div class="feature-visual'+(' blue' if blue else '')+f'">{inside}<span class="visual-label">Illustrative workspace</span></div><div class="feature-copy"><div class="feature-number">{n:02}</div><h2>{title}</h2><p>{text}</p><div class="feature-list">'+''.join(f'<span>{t}</span>' for t in tags)+'</div></div></section>'

def use_cases(product):
    data=[('forestry','Forestry & conservation','See the landscape.<br>Coordinate the work.','Bring boundaries, water bodies and field observations into one spatial view.','forest'),('infrastructure','Infrastructure','Keep assets<br>in context.','Map infrastructure and connect inspection records to the assets and areas they belong to.','assets'),('public','Public programmes','Put location<br>behind each decision.','Organise local information by work area and make spatial records useful to programme teams.','civic')]
    if product=='jurisfield':
        data=[('inspections','Field inspections','Every record,<br>with its context.','Give field teams an assigned area and capture observations with location and supporting evidence.','forest'),('surveys','Asset surveys','Know what is there.<br>Know where it is.','Collect structured records and geometry for assets, boundaries and local infrastructure.','assets'),('programmes','Public programmes','A connected workflow<br>from office to field.','Prepare assignments in the office, collect offline and review submissions in their work area.','civic')]
    tabs='';panels=''
    for i,(key,label,title,text,kind) in enumerate(data):
        key=product+'-'+key
        tabs+=f'<button class="use-case-tab" type="button" role="tab" id="tab-{key}" aria-controls="panel-{key}" aria-selected="'+('true' if i==0 else 'false')+f'" tabindex="{0 if i==0 else -1}">{label}</button>'
        panels+=f'<div class="use-case-panel" role="tabpanel" id="panel-{key}" aria-labelledby="tab-{key}" tabindex="0"'+(' hidden' if i else '')+f'><div><span class="use-case-context">Example workflow</span><h3>{title}</h3><p>{text}</p></div>{map_canvas(kind)}</div>'
    return f'<section class="use-cases reveal">{eyebrow("Where it fits")}<h2>Built around real work.</h2><div class="use-case-layout" data-tabs><div class="use-case-tabs" role="tablist" aria-label="{product.capitalize()} use cases">{tabs}</div><div>{panels}</div></div></section>'

