page('/about','About Withso — Company & products','Withso Technologies (OPC) Private Limited is a Chennai-based software company focused on Mapsmith, JurisField, geospatial development and civic technology.',about)

privacy=f'''<div class="container legal-page">{eyebrow('Website policy')}<h1>Privacy policy</h1><p class="legal-meta">Last updated · 7 October 2026</p><p class="intro">This policy covers this Withso company website, operated by {COMPANY}. Product accounts, field records and other in-product data are covered by the notices and policies of the relevant product.</p><h2>Browsing this website</h2><p>This website presents company and product information. It does not require an account, collect form submissions, or include advertising, behavioural analytics or tracking scripts.</p><p>Our hosting provider may process technical information, including IP addresses, browser details and request logs, to deliver and secure the website. Hosting access controls may use essential session cookies.</p><h2>When you contact us</h2><p>If you email us, we receive your email address and the information you send. We use it to respond to your enquiry and maintain the relevant business correspondence. Please share only information needed for your enquiry.</p><h2>Product websites and external links</h2><p>Links to Mapsmith, JurisField, NammaTN and other websites take you to separate services. Their privacy notices explain how those services handle information. This website’s policy does not replace them.</p><h2>Sharing and retention</h2><p>We do not sell personal information collected through correspondence. We share it only with service providers needed to handle the enquiry, where you request it, or when required by law. We retain correspondence for the enquiry, an ongoing business relationship, and any applicable legal obligations.</p><h2>Your requests</h2><p>For privacy questions or requests concerning information in our correspondence, email <a href="mailto:{EMAIL}">{EMAIL}</a>. We will respond as required by applicable law. For product data requests, please use the contact information in that product’s privacy notice.</p><h2>Changes and contact</h2><p>We will update the date on this page when this website policy changes.</p><p>{COMPANY}<br>CIN: U74103TN2025OPC177570<br>766, Tower 1, Shakti Towers, Ground Floor, Anna Salai,<br>Chennai, India – 600002<br><a href="mailto:{EMAIL}">{EMAIL}</a></p></div>'''
page('/privacy','Privacy policy | Withso','How Withso’s company website handles technical information, email correspondence, external links and privacy requests.',privacy)

terms=f'''<div class="container legal-page">{eyebrow('Website terms')}<h1>Terms &amp; conditions</h1><p class="legal-meta">Last updated · 7 October 2026</p><p class="intro">These terms apply to this company website, operated by {COMPANY}. Please read them alongside our <a href="/privacy">Privacy policy</a>.</p><h2>Using this website</h2><p>You may browse this website and use its information for lawful purposes. You must not interfere with its operation, attempt unauthorised access, distribute malicious content or infringe the rights of others.</p><h2>Product information</h2><p>This website introduces our products and work. Product availability, features and commercial terms may change. A product’s own terms, privacy policy and any written agreement govern use of that product. Illustrative workspaces use sample data and are not live product sessions.</p><h2>Copyright and intellectual property</h2><p>The website’s original text, design and brand assets belong to Withso or their respective owners. You may link to these pages and refer to our products with attribution. These terms do not grant a licence to our software or permit unauthorised redistribution of our content. Third-party names belong to their respective owners.</p><h2>External services</h2><p>Links may open separate websites. Those services operate under their own terms and policies. Providing a link does not create a guarantee about their availability or content.</p><h2>Availability and liability</h2><p>We aim to keep this website accurate and available, but provide its information as available, without a guarantee of uninterrupted service or suitability for a particular purpose. Nothing in these terms excludes liability or rights that cannot lawfully be excluded.</p><h2>Applicable law</h2><p>These website terms are governed by the laws of India. Any applicable mandatory rights remain in place.</p><h2>Changes and contact</h2><p>We may revise these terms by publishing an updated version and date on this page. For website enquiries or copyright concerns, contact <a href="mailto:{EMAIL}">{EMAIL}</a>.</p><p>{COMPANY}<br>CIN: U74103TN2025OPC177570<br>766, Tower 1, Shakti Towers, Ground Floor, Anna Salai,<br>Chennai, India – 600002</p></div>'''
page('/terms','Terms & conditions | Withso','Terms for using Withso’s company website, product information, original content and external links.',terms)

# Legacy paths keep company policy links usable when moving the domain.
for old,new in [('/legal/privacy-policy','/privacy'),('/legal/terms','/terms')]:
    src=DIST/new.lstrip('/')/'index.html';dest=DIST/old.lstrip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(src.read_text())
page('/404','Page not found | Withso','This page could not be found. Explore Withso, Mapsmith and JurisField.',f'<div class="container notfound">{eyebrow("Withso")}<h1>Page not found.</h1><p>The page may have moved. Explore our products from the homepage.</p>{link("/","Back to Withso","button")}</div>')
(DIST/'404.html').write_text((DIST/'404/index.html').read_text())
(DIST/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ORIGIN+r+'</loc></url>' for r in ['/','/mapsmith','/jurisfield','/about','/privacy','/terms'])+'</urlset>')
print('Generated homepage, 2 product pages, About, Privacy, Terms, legacy policy paths and 404.')
